/** Canonical planning datasets: URLs are generated by the server, never by the model. */
export const planningDatasets = [
 {id:'resources',name:'资源池',endpoint:'resources',key:'',editable:true},
 {id:'resource-load',name:'资源负荷',endpoint:'resource-load',key:'resources',editable:false},
 {id:'allocations',name:'作业资源分配表',endpoint:'resource-load',key:'assignments',editable:false},
 {id:'costs',name:'费用明细',endpoint:'cost-dashboard',key:'rows',editable:false},
 {id:'calendar',name:'日历管理',endpoint:'calendar',key:'config',editable:false},
] as const;
export function planningDataset(id:string){return planningDatasets.find(d=>d.id===id)}
